--
-- Table structure for table `hrm_attendance_clock`
--

DROP TABLE IF EXISTS `hrm_attendance_clock`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_attendance_clock` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '打卡记录编号',
  `employee_id` bigint DEFAULT NULL COMMENT '打卡员工编号',
  `clock_time` datetime NOT NULL COMMENT '打卡时间',
  `type` tinyint NOT NULL COMMENT '打卡类型：1 上班，2 下班',
  `attendance_time` datetime NOT NULL COMMENT '应打卡时间',
  `source_type` tinyint NOT NULL DEFAULT '2' COMMENT '来源：1 手机端，2 手工录入，3 自动打卡',
  `status` tinyint DEFAULT '0' COMMENT '打卡状态：0 正常，1 迟到，2 早退，3 缺卡，4 加班',
  `stage` int DEFAULT '1' COMMENT '打卡阶段',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考勤地址',
  `longitude` decimal(10,6) DEFAULT NULL COMMENT '经度',
  `latitude` decimal(10,6) DEFAULT NULL COMMENT '纬度',
  `ssid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'WiFi 名称',
  `mac` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MAC 地址',
  `photo_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '打卡现场照片（人脸/工地照）地址',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_attendance_clock_employee_id` (`employee_id`) USING BTREE,
  KEY `idx_hrm_attendance_clock_time` (`clock_time`) USING BTREE,
  KEY `idx_hrm_attendance_clock_status` (`status`) USING BTREE,
  KEY `idx_hrm_attendance_clock_attendance_time` (`attendance_time`) USING BTREE,
  KEY `idx_hrm_attendance_clock_source_type` (`source_type`) USING BTREE,
  KEY `idx_hrm_attendance_clock_stage` (`stage`) USING BTREE,
  KEY `idx_hrm_att_clock_employee_clock_time` (`employee_id`,`clock_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=691 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 打卡记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

