/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_employee_certificate` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '证书编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `type_id` bigint DEFAULT NULL COMMENT '证照类型编号（hrm_certificate_type.id）',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书名称',
  `level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书级别',
  `no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书编号',
  `start_time` datetime DEFAULT NULL COMMENT '有效起始日期',
  `end_time` datetime DEFAULT NULL COMMENT '有效结束日期',
  `review_date` date DEFAULT NULL COMMENT '复审日期',
  `issuing_authority` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发证机构',
  `issuing_time` datetime DEFAULT NULL COMMENT '发证日期',
  `file_urls` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证件扫描件/照片（逗号分隔地址串）',
  `verify_status` tinyint NOT NULL DEFAULT '0' COMMENT '核验状态：0 未核验，1 已核验，2 核验不通过',
  `verify_user_id` bigint DEFAULT NULL COMMENT '核验人（后台用户编号）',
  `verify_time` datetime DEFAULT NULL COMMENT '核验时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `sort` int DEFAULT NULL COMMENT '排序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户编号',
  `review_time` datetime DEFAULT NULL COMMENT '复审日期',
  `attachment_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证件附件地址',
  `status` tinyint DEFAULT NULL COMMENT '证件状态：1 有效，2 即将到期，3 过期，4 注销',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_hrm_employee_certificate_employee_id` (`employee_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 员工证书表';
