--
-- Table structure for table `hrm_recruit_resume`
--

DROP TABLE IF EXISTS `hrm_recruit_resume`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_recruit_resume` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `candidate_id` bigint NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `file_url` varchar(1024) NOT NULL,
  `version_no` int NOT NULL,
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0 当前版本，1 已被替换',
  `remark` varchar(500) DEFAULT NULL,
  `creator` varchar(64) DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `tenant_id` bigint NOT NULL DEFAULT '0',
  `content` text COMMENT '简历内容快照（在线结构化简历）',
  `content_hash` varchar(64) DEFAULT NULL COMMENT '内容指纹',
  `source_personal_version_id` bigint DEFAULT NULL COMMENT '来源个人简历版本编号',
  `post_id` bigint DEFAULT NULL COMMENT '投递职位编号',
  `post_fingerprint` varchar(64) DEFAULT NULL COMMENT '投递时职位内容指纹',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_candidate_version` (`candidate_id`,`version_no`),
  KEY `idx_candidate_id` (`candidate_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 候选人简历版本表';
/*!40101 SET character_set_client = @saved_cs_client */;

