  `start_time` datetime DEFAULT NULL COMMENT '周期开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '周期结束时间',
  `expected_pay_salary` decimal(12,2) DEFAULT '0.00' COMMENT '应发工资',
  `personal_tax` decimal(12,2) DEFAULT '0.00' COMMENT '个人所得税',
  `real_pay_salary` decimal(12,2) DEFAULT '0.00' COMMENT '实发工资',
  `personal_insurance_amount` decimal(12,2) DEFAULT '0.00' COMMENT '个人社保',
  `personal_provident_fund_amount` decimal(12,2) DEFAULT '0.00' COMMENT '个人公积金',
