--
-- Table structure for table `hrm_salary_option_template`
--

DROP TABLE IF EXISTS `hrm_salary_option_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hrm_salary_option_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `code` int NOT NULL COMMENT '薪资项编码',
  `parent_code` int NOT NULL DEFAULT '0' COMMENT '父级编码',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '薪资项名称',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `system_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否系统默认项',
  `type` tinyint NOT NULL DEFAULT '1' COMMENT '薪资项类型：0 减项，1 加项，2 计算项',
  `tax_enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否计税',
  `visible` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否显示',
  `calculate_enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否参与计算',
  `sort` int DEFAULT NULL COMMENT '兼容旧运行包排序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_hrm_salary_option_template_code` (`code`) USING BTREE,
  KEY `idx_hrm_salary_option_template_parent_code` (`parent_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=86 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='HRM 标准薪资项目录表';
/*!40101 SET character_set_client = @saved_cs_client */;

