INSERT INTO `hrm_salary_option_template` VALUES (1,10,0,'基本工资',NULL,_binary '\0',1,_binary '',_binary '',_binary '',10,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(2,10101,10,'基本工资','劳动合同中约定的标准工资。',_binary '\0',1,_binary '',_binary '',_binary '',10101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(3,10102,10,'岗位工资','根据岗位、责任、技能要求等，不同岗位，工资不同。',_binary '\0',1,_binary '',_binary '',_binary '',10102,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(4,10103,10,'职务工资','根据职务高低、业务技术水平等因素的不同，工资不同，随职务变动而变动。',_binary '\0',1,_binary '',_binary '',_binary '',10103,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(5,20,0,'津补贴','企业给员工提供的福利',_binary '\0',1,_binary '',_binary '',_binary '',20,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(6,20101,20,'住房补贴','为职工解决住房问题而给予的补贴资助。',_binary '\0',1,_binary '',_binary '',_binary '',20101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(7,20102,20,'高温津贴','用人单位安排劳动者在高温天气下工作，当温度高于33℃，应支付高温补贴。',_binary '\0',1,_binary '',_binary '',_binary '',20102,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(8,20103,20,'交通补贴','企业按月按标准支付的交通补贴',_binary '\0',1,_binary '',_binary '',_binary '',20103,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(9,20104,20,'餐补','企业不统一供餐，而是按月按标准支付的午饭或晚餐补贴',_binary '\0',1,_binary '',_binary '',_binary '',20104,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(10,30,0,'浮动工资','浮动工资需要在每月算薪前手工录入',_binary '\0',1,_binary '',_binary '',_binary '',30,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(11,30101,30,'绩效工资','以员工的实际劳动成果或表现为考核标准，支付一定的奖励工资。',_binary '\0',1,_binary '',_binary '',_binary '',30101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(12,40,0,'奖金',NULL,_binary '\0',1,_binary '',_binary '',_binary '',40,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(13,40101,40,'季度奖','对于表现优秀的员工，按季度给予一定的奖励工资。',_binary '\0',1,_binary '',_binary '',_binary '',40101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(14,40102,40,'全勤奖','对于按公司规定到岗工作，未出现任何迟到、早退的员工给予的奖励，一般以月度为考核期限。',_binary '\0',1,_binary '',_binary '',_binary '',40102,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(15,40103,40,'推荐奖','企业在招揽人才的过程中，对推荐人才并顺利入职的内部员工，给予的奖励工资。',_binary '\0',1,_binary '',_binary '',_binary '',40103,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(16,50,0,'提成工资',NULL,_binary '\0',1,_binary '',_binary '',_binary '',50,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(17,50101,50,'销售提成','对于销售或业务人员，通常按照一定的比例，企业和员工之间对盈利进行分成。',_binary '\0',1,_binary '',_binary '',_binary '',50101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(18,60,0,'计件工资',NULL,_binary '\0',1,_binary '',_binary '',_binary '',60,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(19,60101,60,'计件工资','根据职工完成的劳动数量和按事先规定的计件单价计算和支付的工资。',_binary '\0',1,_binary '',_binary '',_binary '',60101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(20,70,0,'计时工资',NULL,_binary '\0',1,_binary '',_binary '',_binary '',70,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(21,70101,70,'计时工资','根据职工的工作时间,按照工资标准、等级计算和支付的工资',_binary '\0',1,_binary '',_binary '',_binary '',70101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(22,80,0,'工龄/司龄工资',NULL,_binary '\0',1,_binary '',_binary '',_binary '',80,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(23,80101,80,'工龄工资','企业按照员工的工作年数，即员工的工作经验和劳动贡献的积累给予的经济补偿。',_binary '\0',1,_binary '',_binary '',_binary '',80101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(24,80102,80,'司龄工资','司龄工资是按照劳动者在在公司做的时间的长短进行相应工资的计算。',_binary '\0',1,_binary '',_binary '',_binary '',80102,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(25,90,0,'职称工资',NULL,_binary '\0',1,_binary '',_binary '',_binary '',90,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(26,90101,90,'职称工资','工资高低与职称挂钩，职称越高，工资越高。',_binary '\0',1,_binary '',_binary '',_binary '',90101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(27,90102,90,'技能工资','以员工个人所掌握的知识、技术和所具备的能力为基础来进行工资报酬的支付。',_binary '\0',1,_binary '',_binary '',_binary '',90102,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(28,90103,90,'学历工资','根据员工在教育机构取得的学历而给予适当的津贴。',_binary '\0',1,_binary '',_binary '',_binary '',90103,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(29,100,0,'代扣代缴','公司代替个人缴纳的费用，如个人社保、个人公积金。该类别下的薪酬项，将从应纳税所得额中扣除，影响个税计算',_binary '\0',0,_binary '',_binary '',_binary '',100,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(30,100101,100,'个人社保','社保中个人缴纳的部分',_binary '\0',0,_binary '',_binary '',_binary '',100101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(31,100102,100,'个人公积金','公积金中个人缴纳的部分',_binary '\0',0,_binary '',_binary '',_binary '',100102,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(32,110,0,'企业社保','该类别下的薪酬项，不参与工资计算，只参与企业成本统计或社保成本分析',_binary '\0',1,_binary '\0',_binary '',_binary '\0',110,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(33,110101,110,'企业社保','企业承担的社保费用',_binary '\0',1,_binary '\0',_binary '',_binary '\0',110101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(34,120,0,'企业公积金','该类别下的薪酬项，不参与工资计算，只参与企业成本统计或社保成本分析',_binary '\0',1,_binary '\0',_binary '',_binary '\0',120,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(35,120101,120,'企业公积金','企业承担的公积金费用',_binary '\0',1,_binary '\0',_binary '',_binary '\0',120101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(36,130,0,'税前补发','税前补发，与该月的工资一起发放，需参与计税',_binary '\0',1,_binary '\0',_binary '',_binary '',130,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(37,130101,130,'税前补发','如上月漏发，这月补发的工资',_binary '\0',1,_binary '\0',_binary '',_binary '',130101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(38,140,0,'税前补扣','税前从该月的工资中补扣的金额，会影响本月的应税工资总额',_binary '\0',0,_binary '\0',_binary '',_binary '',140,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(39,140101,140,'税前补扣','如上月未扣，这月补扣的扣款；',_binary '\0',0,_binary '\0',_binary '',_binary '',140101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(40,150,0,'税后补发','税后补发，不参与该月工资计算，会影响当月的实际所得',_binary '\0',1,_binary '\0',_binary '',_binary '',150,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(41,150101,150,'税后补发','其它税后补发',_binary '\0',1,_binary '\0',_binary '',_binary '',150101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(42,160,0,'税后补扣','从税后的工资中补扣的款项，不参与该月的工资计税',_binary '\0',0,_binary '\0',_binary '',_binary '',160,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(43,160101,160,'党费','向党组织交纳的用于党的事业和党的活动的经费，由公司代收。',_binary '\0',0,_binary '\0',_binary '',_binary '',160101,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(44,160102,160,'工会费','员工缴纳的，工会组织开展各项活动所需要的费用',_binary '\0',0,_binary '\0',_binary '',_binary '',160102,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(45,160103,160,'补充医疗','企业在基本医疗保险的基础上，为员工缴纳的额外补充医疗保险。',_binary '\0',0,_binary '\0',_binary '',_binary '',160103,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52:10',_binary '\0'),(46,170,0,'特殊计税项','其它里的科目不参与工资计算，但要计税',_binary '\0',1,_binary '',_binary '',_binary '',170,'admin','2026-07-25 17:28:06','admin','2026-07-26 04:52: